import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {promptBuilder, sessionWith, rejectingWith} from './testSupport.js';

describe('ChatOrchestrator onError on non-Error rejections (round test)', () => {
  it('calls onError with an Error when provider rejects with a string', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith('string boom'), promptBuilder, undefined, {hooks});

    let thrown: unknown;
    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      thrown = e;
    }

    expect({
      thrown,
      isError: receivedError instanceof Error,
      message: receivedError?.message,
    }).toEqual({
      thrown: 'string boom',
      isError: true,
      message: 'string boom',
    });
  });

  it('calls onError with an Error when provider rejects with a plain object', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const reason = {code: 500, message: 'internal error'};
    const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});

    let thrown: unknown;
    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      thrown = e;
    }

    expect({
      thrown,
      isError: receivedError instanceof Error,
      cause: receivedError?.cause,
    }).toEqual({
      thrown: reason,
      isError: true,
      cause: reason,
    });
  });

  it('calls onError with an Error when provider rejects with undefined', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(undefined), promptBuilder, undefined, {hooks});

    let thrown: unknown;
    let thrownSeen = false;
    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      thrown = e;
      thrownSeen = true;
    }

    expect({
      thrownSeen,
      thrown,
      isError: receivedError instanceof Error,
      cause: receivedError?.cause,
    }).toEqual({
      thrownSeen: true,
      thrown: undefined,
      isError: true,
      cause: undefined,
    });
  });
});

